+  Props: TSqlDBConnectionProperties; const TableName: RawUtf8;
+  const FieldNames: TRawUtf8DynArray; const FieldTypes: TSqlDBFieldTypeArray;
+  RowCount: integer; const FieldValues: TRawUtf8DynArrayDynArray;
